import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def read(p): return json.loads((ROOT/p).read_text(encoding='utf-8'))
def save(p,v): (ROOT/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
library=read('audit/source-notes.json')
def src(key,url,locator,evidence,limitations='Published primary account; historical claims are bounded to the cited version.'):
    key='b34-'+key
    library['sources'][key]=dict(url=url,locator=locator,evidence=evidence,checkedBy='Codex',checkedAt='2026-11-09',timeSensitive=False,nextReviewAt=None,limitations=limitations,topics=['parks','walt'])
    return key
